+fn reaches_edge(stock: &Region, run: &[Point2], z: f64) -> Result<(), GenError> {
+    let ends = [("start", run[0]), ("end", run[run.len() - 1])];
+    for (name, q) in ends {
+        let d = depth(stock, q);
+        if d.is_nan() || d > EDGE_TOL {
